:root {
  color-scheme: dark;
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  font-size: 16px;
  background: #182a35;
  color: #f5f0dc;
  --ink: #182a35;
  --panel: #233944;
  --cream: #f5f0dc;
  --mint: #9be3bd;
  --coral: #ff806e;
}

* { box-sizing: border-box; }
body {
  min-width: 360px;
  min-height: 100vh;
  margin: 0;
  display: grid;
  place-items: center;
  padding: 24px 16px;
  background-color: var(--ink);
  background-image: radial-gradient(#3c5960 1.5px, transparent 1.5px);
  background-size: 24px 24px;
}
button { font: inherit; }
.board {
  width: min(100%, 680px);
  padding: clamp(24px, 6vw, 48px);
  border: 4px solid var(--mint);
  background: var(--panel);
  box-shadow: 10px 10px 0 #101d25;
  text-align: center;
}
.header { margin-bottom: 30px; }
.eyebrow, .result-label, .round-label {
  color: var(--mint);
  font-size: 0.8rem;
  font-weight: 800;
  letter-spacing: 0.14em;
}
h1 {
  margin: 8px 0;
  color: var(--cream);
  font-size: clamp(2rem, 8vw, 3.25rem);
  line-height: 1.05;
  letter-spacing: -0.05em;
}
.subtitle { margin: 0; color: #c8d7ce; font-size: 1.05rem; }
.game {
  padding: clamp(18px, 4vw, 28px);
  border: 2px solid #49636a;
  background: #1c3039;
}
.status-row { display: flex; justify-content: space-between; align-items: center; gap: 12px; }
.round-label { color: #c8d7ce; }
.round-label strong { color: var(--mint); }
.roll-count { color: var(--cream); font-weight: 700; }
.dice-tray {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: clamp(7px, 2vw, 14px);
  margin: 28px 0 12px;
}
.die {
  position: relative;
  display: grid;
  place-items: center;
  aspect-ratio: 1;
  min-width: 0;
  padding: 6px;
  border: 3px solid var(--cream);
  border-radius: 8px;
  background: var(--cream);
  color: var(--ink);
  box-shadow: 4px 4px 0 #101d25;
  cursor: pointer;
  transition: transform 120ms ease, background 120ms ease, border-color 120ms ease;
}
.die:hover { transform: translateY(-3px); }
.die:active { transform: translateY(1px); box-shadow: 2px 2px 0 #101d25; }
.die:focus-visible, button:focus-visible { outline: 3px solid #fff; outline-offset: 4px; }
.die.held { border-color: var(--coral); background: #ffe0b8; transform: translateY(-5px); }
.die .pip-grid {
  display: grid;
  grid-template: repeat(3, 1fr) / repeat(3, 1fr);
  width: 78%;
  height: 78%;
  align-items: center;
  justify-items: center;
}
.pip {
  width: clamp(5px, 1.5vw, 11px);
  aspect-ratio: 1;
  border-radius: 2px;
  background: var(--ink);
}
.pip:nth-child(1) { grid-area: 1 / 1; }
.pip:nth-child(2) { grid-area: 1 / 3; }
.pip:nth-child(3) { grid-area: 2 / 1; }
.pip:nth-child(4) { grid-area: 2 / 2; }
.pip:nth-child(5) { grid-area: 2 / 3; }
.pip:nth-child(6) { grid-area: 3 / 1; }
.pip:nth-child(7) { grid-area: 3 / 3; }
.die[data-value="1"] .pip:nth-child(n+2),
.die[data-value="2"] .pip:nth-child(n+3),
.die[data-value="3"] .pip:nth-child(n+4),
.die[data-value="4"] .pip:nth-child(n+5),
.die[data-value="5"] .pip:nth-child(n+6),
.die[data-value="6"] .pip:nth-child(n+7) { visibility: hidden; }
.held-tag {
  position: absolute;
  top: calc(100% + 8px);
  color: var(--coral);
  font-size: 0.68rem;
  font-weight: 900;
  letter-spacing: 0.08em;
}
.hint { min-height: 1.5em; margin: 18px 0; color: #c8d7ce; }
.result {
  display: grid;
  gap: 4px;
  padding: 16px;
  border: 1px dashed #668079;
}
.result-label { font-size: 0.7rem; }
#hand-name { color: var(--mint); font-size: clamp(1.2rem, 4vw, 1.65rem); }
.actions { display: flex; justify-content: center; flex-wrap: wrap; gap: 12px; margin-top: 22px; }
.actions button {
  min-height: 48px;
  padding: 10px 20px;
  border: 2px solid transparent;
  font-weight: 800;
  cursor: pointer;
  transition: transform 120ms ease, filter 120ms ease;
}
.actions button:hover { transform: translateY(-2px); filter: brightness(1.08); }
.actions button:active { transform: translateY(1px); }
.roll-button { background: var(--mint); color: var(--ink); }
.roll-button span { padding-left: 8px; font-size: 1.2em; }
.new-button { border-color: #809795 !important; background: transparent; color: var(--cream); }
.actions button:disabled { cursor: not-allowed; filter: grayscale(0.7); opacity: 0.55; transform: none; }
footer { margin-top: 24px; color: #b5c6be; font-size: 0.9rem; }
@media (max-width: 420px) {
  .board { padding: 22px 16px; box-shadow: 6px 6px 0 #101d25; }
  .die { border-width: 2px; border-radius: 6px; }
  .held-tag { font-size: 0.58rem; }
}
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { transition-duration: 0.01ms !important; } }

const tray = document.querySelector("#dice-tray");
const rollButton = document.querySelector("#roll-button");
const newButton = document.querySelector("#new-button");
const rollCount = document.querySelector("#roll-count");
const handName = document.querySelector("#hand-name");
const hint = document.querySelector("#hint");
const roundNumber = document.querySelector("#round-number");

let dice = [];
let rerollsLeft = 2;
let round = 1;
let finished = false;

function classify(values) {
  const counts = Object.values(values.reduce((map, value) => {
    map[value] = (map[value] || 0) + 1;
    return map;
  }, {})).sort((a, b) => b - a);
  const unique = [...new Set(values)].sort((a, b) => a - b);
  const straight = unique.length === 5 && (unique[4] - unique[0] === 4 || unique.join("") === "12356");

  if (counts[0] === 5) return "Five of a kind";
  if (counts[0] === 4) return "Four of a kind";
  if (counts[0] === 3 && counts[1] === 2) return "Full house";
  if (straight) return "Straight";
  if (counts[0] === 3) return "Three of a kind";
  if (counts[0] === 2 && counts[1] === 2) return "Two pair";
  if (counts[0] === 2) return "Pair";
  return "No pair";
}

function render() {
  tray.replaceChildren();
  dice.forEach((die, index) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = `die${die.held ? " held" : ""}`;
    button.dataset.value = die.value;
    button.setAttribute("aria-pressed", String(die.held));
    button.setAttribute("aria-label", `Die ${index + 1}: ${die.value}${die.held ? ", held" : ", not held"}. Click to ${die.held ? "release" : "hold"}.`);

    const grid = document.createElement("span");
    grid.className = "pip-grid";
    grid.setAttribute("aria-hidden", "true");
    for (let pip = 0; pip < 7; pip += 1) {
      const dot = document.createElement("span");
      dot.className = "pip";
      grid.append(dot);
    }
    button.append(grid);
    if (die.held) {
      const tag = document.createElement("span");
      tag.className = "held-tag";
      tag.textContent = "HELD";
      button.append(tag);
    }
    button.addEventListener("click", () => {
      if (finished) return;
      die.held = !die.held;
      render();
    });
    tray.append(button);
  });

  rollCount.textContent = `${rerollsLeft} ${rerollsLeft === 1 ? "reroll" : "rerolls"} left`;
  rollButton.disabled = finished || rerollsLeft === 0;
}

function startRound() {
  roundNumber.textContent = String(round).padStart(2, "0");
  dice = Array.from({ length: 5 }, () => ({ value: Math.ceil(Math.random() * 6), held: false }));
  rerollsLeft = 2;
  finished = false;
  handName.textContent = "Ready to roll";
  hint.textContent = "Select dice to hold, then roll again.";
  render();
}

rollButton.addEventListener("click", () => {
  if (finished || rerollsLeft === 0) return;
  dice = dice.map((die) => ({
    value: die.held ? die.value : Math.ceil(Math.random() * 6),
    held: die.held
  }));
  rerollsLeft -= 1;
  handName.textContent = rerollsLeft === 0 ? classify(dice.map((die) => die.value)) : "Keep going…";
  hint.textContent = rerollsLeft === 0 ? "Round complete. Start a new round to play again." : "Select dice to hold for your final roll.";
  finished = rerollsLeft === 0;
  render();
});

newButton.addEventListener("click", () => {
  round += 1;
  startRound();
});

startRound();
